        "평가사유": "[화제성 8점] (확정 →) 『과학콘서트』『열두 발자국』의 베스트셀러 저자이자 방송 인지도가 높은 정재승의 8년 만의 단독 신간. 출간 직전 알라딘 판매지수 21,240으로 이번 배치 최상위권 예판 신호, 예스24도 신간 알림 이벤트를 운영. (추정 →) 출간 후 종합 베스트셀러 상위 진입 가능성 높음.\n[독창성 5점] (독점성·희소성·차별 기획 관점) 국내 저자라 인터뷰·출연 섭외 현실성이 높다는 점은 가점. 다만 'AI 시대 인간의 자리'는 이미 포화된 주제이고, 출간 즉시 언론 북섹션·북튜브가 일제히 다룰 책이라 독점 각도는 섭외 성사 여부에 달려 있다.\n[근접성 8점] (한국 독자 친숙도·주제 대중성·접근성) AI는 현재 한국 사회 최대 관심사 중 하나이고, 저자의 대중 친화적 문체·방송 이미지로 일반 독자 접근성이 높다. 대형 서점 매대 노출 확실.\n[영향성 8점] (판매·의제화·영상화 연계·브랜드 기여) 대형 판매가 예상되고 강연·대담·방송 패널 연계가 쉬워 채널 브랜드 기여 여지가 크다. 의제화도 AI 담론과 맞물려 가능.\n[종합] 강점: 검증된 베스트셀러 저자 + 시의적 AI 주제 + 높은 예판 지표. 약점·리스크: 주제 자체는 흔해 경쟁 매체와 차별이 어렵고, 실제 내용(대담 형식 여부 등) 책소개가 서점에 아직 충분히 공개되지 않음. 편성 관점 — 이번 배치 최우선 아이템, 저자 단독 인터뷰/대담 섭외를 조기에 시도할 가치.",
