        "개요": "전 세계 수천만의 독자들은 이미 『다빈치 코드』가 다른 어떤 책에서도 맛보지 못한 놀라운 경험을 안겨 준다는 사실을 확인했다. 놀라운 속도감, 치밀한 자료 조사를 통한 지적이고 흥미진진한 복선, 댄 브라운의 소설은 첫 페이지부터 놀라운 결말에 이르기까지, 흠잡을 데 없는 걸작이다.",
