        "평가사유": "[화제성 10점] (일정 확정 / 동원은 직전 회차 실적 →) 직전 시즌 '2025 서울윈터페스타'가 24일간 누적 1,098만 명으로 전년(539만)의 2배를 넘겨 서울시 겨울축제 기록을 모두 경신했다. 2026 회차는 59일·거점 확대로 더 커진다. 이번 윈도우에서 동원 규모가 압도적 1위다.\n[독창성 8점] (영상 소재성 / 규모) 한강·광화문광장·청계천·서울광장·보신각·DDP를 빛과 미디어아트로 잇는 구성 자체가 완성된 영상 소재이고, 개막 퍼레이드·신년 카운트다운까지 별도 후크가 붙는다. 다만 서울시 주최 개방 행사라 독점 확보는 불가능하고 경쟁 매체가 같은 그림을 찍는다.\n[근접성 10점] 수도권 한복판 + 전면 무료 + 야외 개방 + 지하철 도보권. 접근성·친숙도 최상.\n[영향성 9점] 전국 뉴스 노출과 연말 의제 선점, 외래관광객 유치 성과 보도가 매년 반복되며 채널 브랜드 기여가 크다.\n[종합] 강점: 이번 윈도우 최대 동원, 무료, 수도권, 59일 상설이라 취재 일정이 자유롭다. 약점·리스크: 독점성 전무, 한파 시 체류시간 급감, 1천만 인파의 안전관리 이슈가 곧 사건 리스크다. 또 서울라이트 광화문(12/11)과 서울빛초롱축제(11/1)가 이 축제의 하위/연계 프로그램이라 셋을 각각 편성하면 같은 그림이 3번 나간다. 편성: 이번 회차 최우선 확보 — 12/4 개막과 12/31 카운트다운으로 나눠 2회 기획하고, 서울라이트·빛초롱은 별도 편성하지 말고 이 안에서 소화.",
